107	// isSupportedVerb returns whether or not a APIResource supports a specific verb.
108	// The verb will be matched case-insensitive.
109	func isSupportedVerb(apiResource *metav1.APIResource, verb string) bool {
110		if verb == "" || verb == "*" {
111			return true
112		}
113		for _, v := range apiResource.Verbs {
114			if strings.EqualFold(v, verb) {
115				return true
116			}
117		}
118		return false
119	}
